object Solution {
  def soonestAndFurthestRound(n: Int, firstPlayer: Int, secondPlayer: Int): Array[Int] = {
    // We will simulate rounds with a recursive DFS approach.
    // At each round, we have a set of contestants (sorted by their original labels).
    // We want to find the earliest and latest round where firstPlayer and secondPlayer meet.
    //
    // Key points:
    // - firstPlayer and secondPlayer always win against others.
    // - When they meet, the round is recorded.
    // - For other matches, we can pick the winner to maximize or minimize the round they meet.
    //
    // Approach:
    // - Represent current contestants as a sorted array.
    // - Pair contestants from front and back.
    // - If firstPlayer and secondPlayer meet, return (round, round).
    // - Otherwise, for each pair:
    //   - If one is firstPlayer or secondPlayer, that one wins.
    //   - If neither, we can choose either to win (try both).
    // - If odd number, middle contestant gets a bye.
    //
    // Use memoization to avoid recomputing states.
    //
    // State can be represented by a bitmask of contestants present.
    // We know n <= 28, so bitmask fits in Long.
    //
    // We'll store memo: Map[(Long, Int), (Int, Int)] = (minRound, maxRound)
    //
    // The initial bitmask has bits set for all contestants 1..n.
    // firstPlayer and secondPlayer are fixed.

    import scala.collection.mutable

    val FULL_MASK: Long = (1L << n) - 1
    val fpBit = 1L << (firstPlayer - 1)
    val spBit = 1L << (secondPlayer - 1)

    val memo = mutable.Map.empty[(Long, Int), (Int, Int)]

    def bitCount(x: Long): Int = java.lang.Long.bitCount(x)

    // Extract contestants from bitmask in ascending order
    def contestants(mask: Long): Array[Int] = {
      val arr = new Array[Int](bitCount(mask))
      var idx = 0
      var m = mask
      while (m != 0) {
        val lowest = m & (-m)
        val pos = java.lang.Long.numberOfTrailingZeros(lowest)
        arr(idx) = pos + 1
        idx += 1
        m ^= lowest
      }
      arr
    }

    def dfs(mask: Long, round: Int): (Int, Int) = {
      if (memo.contains((mask, round))) return memo((mask, round))

      val arr = contestants(mask)
      val len = arr.length

      // If firstPlayer and secondPlayer both not in mask, no meeting possible
      if ((mask & fpBit) == 0 || (mask & spBit) == 0) {
        // They can't meet anymore
        memo((mask, round)) = (Int.MaxValue, Int.MinValue)
        return (Int.MaxValue, Int.MinValue)
      }

      // Check if they meet this round:
      // Pair i-th from front and i-th from back:
      // If firstPlayer and secondPlayer are paired, return (round, round)
      val half = len / 2
      for (i <- 0 until half) {
        val front = arr(i)
        val back = arr(len - 1 - i)
        if ((front == firstPlayer && back == secondPlayer) || (front == secondPlayer && back == firstPlayer)) {
          memo((mask, round)) = (round, round)
          return (round, round)
        }
      }

      // If only one contestant remains, no meeting possible
      if (len == 1) {
        memo((mask, round)) = (Int.MaxValue, Int.MinValue)
        return (Int.MaxValue, Int.MinValue)
      }

      // Build pairs and possible winners for next round
      // For each pair:
      // - If contains firstPlayer or secondPlayer, that one wins
      // - Else, we can choose either to win (try both)
      //
      // If odd length, middle contestant gets bye

      // We'll generate all possible next round survivors sets and combine results

      // To avoid exponential explosion, we prune by memoization and careful branching

      // We'll do DFS with backtracking on pairs without fp/sp, choosing winner either side

      // Prepare pairs:
      val pairs = (0 until half).map(i => (arr(i), arr(len - 1 - i))).toArray
      val hasBye = (len % 2 == 1)
      val byeContestant = if (hasBye) Some(arr(half)) else None

      // For pairs, determine forced winner or both options
      // We'll generate all combinations of winners for pairs without fp/sp

      // For each pair:
      // - If contains fp or sp, winner forced
      // - Else, two options

      // We'll do a backtracking over pairs to generate all possible next round masks

      var minRound = Int.MaxValue
      var maxRound = Int.MinValue

      def backtrack(i: Int, survivors: List[Int]): Unit = {
        if (i == pairs.length) {
          // Add bye contestant if any
          val nextSurvivors = byeContestant match {
            case Some(c) => c :: survivors
            case None => survivors
          }
          // survivors must be sorted ascending by original label
          val sortedSurvivors = nextSurvivors.sorted
          // Build mask
          var nextMask = 0L
          for (c <- sortedSurvivors) nextMask |= (1L << (c - 1))
          val (minR, maxR) = dfs(nextMask, round + 1)
          if (minR < minRound) minRound = minR
          if (maxR > maxRound) maxRound = maxR
          return
        }

        val (a, b) = pairs(i)
        val aIsFP = (a == firstPlayer)
        val aIsSP = (a == secondPlayer)
        val bIsFP = (b == firstPlayer)
        val bIsSP = (b == secondPlayer)

        if (aIsFP || aIsSP) {
          // a wins forced
          backtrack(i + 1, a :: survivors)
        } else if (bIsFP || bIsSP) {
          // b wins forced
          backtrack(i + 1, b :: survivors)
        } else {
          // both options possible
          backtrack(i + 1, a :: survivors)
          backtrack(i + 1, b :: survivors)
        }
      }

      backtrack(0, Nil)

      memo((mask, round)) = (minRound, maxRound)
      (minRound, maxRound)
    }

    val (minR, maxR) = dfs(FULL_MASK, 1)
    Array(minR, maxR)
  }
